/**
 * One art child of Frame 270, placed in band-local design px. Generated by
 * scripts/frame270.py from Figma's own geometry -- every field is a Figma property, not a
 * measurement.
 */
export type BandLayer = {
  /** Global Figma paint order -- bands share one stacking context, so this is comparable across them. */
  z: number
  id: string
  src: string
  /** The element box before rotation: Figma's unrotated size, centred where the node sits. */
  x: number
  y: number
  w: number
  h: number
  /** Rotation in degrees, applied after `fy` (CSS `rotate`, then `scale`, as Figma composes them). */
  r?: number
  /** Figma's flip: scaleY(-1). With r: 180 it is a plain horizontal mirror. */
  fy?: boolean
  /** The fill's own placement inside the box, in % -- [left, top, width, height] -- when Figma crops it. */
  crop?: [number, number, number, number]
  /** `fill` stretches the image to the box; the default `cover` keeps its aspect. */
  fit?: 'cover' | 'fill'
  /** Layer opacity. Absent means 1. */
  a?: number
  /** Corner radius, design px. */
  radius?: number
  /** Drop shadow [x, y, blur, colour], design px. */
  shadow?: [number, number, number, string]
  /** Inner shadow [x, y, blur, colour], design px. */
  inset?: [number, number, number, string]
  /** An alpha mask: another asset placed at x/y (relative to this box) at w x h, design px. */
  mask?: { src: string; x: number; y: number; w: number; h: number }
}
